1	import { useEffect } from "react";
2	import { Link, useSearchParams } from "react-router";
3	import { toast } from "sonner";
4	import type { Route } from "./+types/courses.$slug";
5	import {
6	  getCourseBySlug,
7	  getCourseWithDetails,
8	  getLessonCountForCourse,
9	} from "~/services/courseService";
10	import { isUserEnrolled } from "~/services/enrollmentService";
11	import {
12	  calculateProgress,
13	  getLessonProgressForCourse,
14	  getNextIncompleteLesson,
15	} from "~/services/progressService";
16	import { getCurrentUserId } from "~/lib/session";
17	import { LessonProgressStatus } from "~/db/schema";
18	import { Card, CardContent, CardHeader } from "~/components/ui/card";
19	import { Button } from "~/components/ui/button";
20	import { Skeleton } from "~/components/ui/skeleton";
21	import {
22	  Tabs,
23	  TabsList,
24	  TabsTrigger,
25	  TabsContent,
26	  TabsContentNoShift,
27	} from "~/components/ui/tabs";
28	import {
29	  AlertTriangle,
30	  BookOpen,
31	  CheckCircle2,
32	  Circle,
33	  Clock,
34	  Pencil,
35	  PlayCircle,
36	  Users,
37	} from "lucide-react";
38	import { CourseImage } from "~/components/course-image";
39	import { UserAvatar } from "~/components/user-avatar";
40	import { data, isRouteErrorResponse } from "react-router";
41	import { formatDuration, formatPrice } from "~/lib/utils";
42	import { renderMarkdown } from "~/lib/markdown.server";
43	import { resolveCountry } from "~/lib/country.server";
44	import { calculatePppPrice, getCountryTierInfo } from "~/lib/ppp";
45	
46	export function meta({ data: loaderData }: Route.MetaArgs) {
47	  const title = loaderData?.course?.title ?? "Course";
48	  return [
49	    { title: `${title} — Cadence` },
50	    { name: "description", content: loaderData?.course?.description ?? "" },
51	  ];
52	}
53	
54	export async function loader({ params, request }: Route.LoaderArgs) {
55	  const slug = params.slug;
56	  const course = getCourseBySlug(slug);
57	
58	  if (!course) {
59	    throw data("Course not found", { status: 404 });
60	  }
61	
62	  const courseWithDetails = getCourseWithDetails(course.id);
63	  if (!courseWithDetails) {
64	    throw data("Course not found", { status: 404 });
65	  }
66	
67	  const lessonCount = getLessonCountForCourse(course.id);
68	  const currentUserId = await getCurrentUserId(request);
69	
70	  let enrolled = false;
71	  let progress = 0;
72	  let lessonProgressMap: Record<number, string> = {};
73	  let nextLessonId: number | null = null;
74	
75	  if (currentUserId) {
76	    enrolled = isUserEnrolled(currentUserId, course.id);
77	
78	    if (enrolled) {
79	      progress = calculateProgress(currentUserId, course.id, false, false);
80	
81	      const progressRecords = getLessonProgressForCourse(
82	        currentUserId,
83	        course.id
84	      );
85	      for (const record of progressRecords) {
86	        lessonProgressMap[record.lessonId] = record.status;
87	      }
88	
89	      const nextLesson = getNextIncompleteLesson(currentUserId, course.id);
90	      nextLessonId = nextLesson?.id ?? null;
91	    }
92	  }
93	
94	  // Render sales copy from Markdown to HTML server-side
95	  const salesCopyHtml = courseWithDetails.salesCopy
96	    ? await renderMarkdown(courseWithDetails.salesCopy)
97	    : null;
98	
99	  const country = await resolveCountry(request);
100	  const pppPrice = courseWithDetails.pppEnabled
101	    ? calculatePppPrice(courseWithDetails.price, country)
102	    : courseWithDetails.price;
103	  const tierInfo = getCountryTierInfo(country);
104	
105	  return {
106	    course: courseWithDetails,
107	    salesCopyHtml,
108	    lessonCount,
109	    enrolled,
110	    progress,
111	    lessonProgressMap,
112	    nextLessonId,
113	    currentUserId,
114	    pppPrice,
115	    tierInfo,
116	  };
117	}
118	
119	// No action — enrollment is handled via the purchase confirmation page
120	
121	export function HydrateFallback() {
122	  return (
123	    <div className="mx-auto max-w-7xl p-6 lg:p-8">
124	      <nav className="mb-6">
125	        <Skeleton className="h-4 w-48" />
126	      </nav>
127	      <div className="mb-8 grid gap-6 lg:grid-cols-3">
128	        <div className="lg:col-span-2">
129	          <Skeleton className="mb-6 aspect-video rounded-lg" />
130	          <Skeleton className="mb-2 h-4 w-20" />
131	          <Skeleton className="mb-3 h-9 w-3/4" />
132	          <Skeleton className="mb-2 h-4 w-full" />
133	          <Skeleton className="mb-4 h-4 w-2/3" />
134	          <div className="flex gap-4">
135	            <Skeleton className="h-4 w-28" />
136	            <Skeleton className="h-4 w-24" />
137	          </div>
138	        </div>
139	        <div>
140	          <Card>
141	            <CardHeader>
142	              <Skeleton className="h-6 w-32" />
143	            </CardHeader>
144	            <CardContent>
145	              <Skeleton className="h-10 w-full" />
146	            </CardContent>
147	          </Card>
148	        </div>
149	      </div>
150	      <Skeleton className="mb-4 h-8 w-40" />
151	      <div className="space-y-4">
152	        {Array.from({ length: 3 }).map((_, i) => (
153	          <Card key={i}>
154	            <CardHeader>
155	              <Skeleton className="h-5 w-48" />
156	              <Skeleton className="h-4 w-20" />
157	            </CardHeader>
158	            <CardContent>
159	              <div className="space-y-2">
160	                {Array.from({ length: 4 }).map((_, j) => (
161	                  <Skeleton key={j} className="h-8 w-full" />
162	                ))}
163	              </div>
164	            </CardContent>
165	          </Card>
166	        ))}
167	      </div>
168	    </div>
169	  );
170	}
171	
172	export default function CourseDetail({ loaderData }: Route.ComponentProps) {
173	  const {
174	    course,
175	    salesCopyHtml,
176	    lessonCount,
177	    enrolled,
178	    progress,
179	    lessonProgressMap,
180	    nextLessonId,
181	    currentUserId,
182	    pppPrice,
183	    tierInfo,
184	  } = loaderData;
185	  const isInstructor = currentUserId === course.instructorId;
186	  const [searchParams, setSearchParams] = useSearchParams();
187	
188	  useEffect(() => {
189	    if (searchParams.get("already_enrolled") === "1") {
190	      toast.info("You're already enrolled in this course.");
191	      setSearchParams(
192	        (prev) => {
193	          prev.delete("already_enrolled");
194	          return prev;
195	        },
196	        { replace: true }
197	      );
198	    }
199	  }, [searchParams, setSearchParams]);
200	
201	  const totalDuration = course.modules.reduce(
202	    (sum, mod) =>
203	      sum + mod.lessons.reduce((s, l) => s + (l.durationMinutes ?? 0), 0),
204	    0
205	  );
206	
207	  const pppPriceLabel = formatPrice(pppPrice);
208	  const isDiscounted = pppPrice < course.price;
209	
210	  const selfPurchaseLink = currentUserId
211	    ? `/courses/${course.slug}/purchase`
212	    : `/signup?redirectTo=${encodeURIComponent(`/courses/${course.slug}/purchase`)}`;
213	
214	  const teamPurchaseLink = currentUserId
215	    ? `/courses/${course.slug}/purchase?mode=team`
216	    : `/signup?redirectTo=${encodeURIComponent(`/courses/${course.slug}/purchase?mode=team`)}`;
217	
218	  const priceDisplay = (
219	    <div className="mb-3 text-center">
220	      {isDiscounted ? (
221	        <>
222	          <div className="text-sm text-muted-foreground line-through">
223	            {formatPrice(course.price)}
224	          </div>
225	          <div className="text-2xl font-bold">{pppPriceLabel}</div>
226	          <div className="mt-1 inline-block rounded-full bg-green-100 px-2.5 py-0.5 text-xs font-medium text-green-800 dark:bg-green-900/30 dark:text-green-300">
227	            {tierInfo.label} — PPP discount
228	          </div>
229	        </>
230	      ) : (
231	        <div className="text-2xl font-bold">{pppPriceLabel}</div>
232	      )}
233	    </div>
234	  );
235	
236	  const enrollButton = (
237	    <Tabs defaultValue="self">
238	      <TabsList className="mb-4 w-full">
239	        <TabsTrigger value="self" className="flex-1 text-xs">
240	          Buy for Myself
241	        </TabsTrigger>
242	        <TabsTrigger value="team" className="flex-1 text-xs">
243	          Buy for Team
244	        </TabsTrigger>
245	      </TabsList>
246	      <TabsContentNoShift>
247	        <TabsContent value="self" forceMount>
248	          {priceDisplay}
249	          <Link to={selfPurchaseLink}>
250	            <Button size="lg" className="w-full">
251	              Enroll Now — {pppPriceLabel}
252	            </Button>
253	          </Link>
254	        </TabsContent>
255	        <TabsContent value="team" forceMount>
256	          {priceDisplay}
257	          <Link to={teamPurchaseLink}>
258	            <Button size="lg" variant="outline" className="w-full">
259	              Buy for Your Team
260	            </Button>
261	          </Link>
262	        </TabsContent>
263	      </TabsContentNoShift>
264	    </Tabs>
265	  );
266	
267	  return (
268	    <div className="mx-auto max-w-7xl p-6 lg:p-8">
269	      {/* Breadcrumb */}
270	      <nav className="mb-6 text-sm text-muted-foreground">
271	        <Link to="/courses" className="hover:text-foreground">
272	          Courses
273	        </Link>
274	        <span className="mx-2">/</span>
275	        <span className="text-foreground">{course.title}</span>
276	      </nav>
277	
278	      {/* Hero section */}
279	      <div className="mb-8">
280	        <div className="mb-6 aspect-video max-h-64 overflow-hidden rounded-lg">
281	          <CourseImage
282	            src={course.coverImageUrl}
283	            alt={course.title}
284	            className="h-full w-full object-cover"
285	          />
286	        </div>
287	        <div className="mb-2 text-sm font-medium text-primary">
288	          {course.categoryName}
289	        </div>
290	        <div className="mb-3 flex items-start justify-between gap-4">
291	          <h1 className="text-4xl font-bold">{course.title}</h1>
292	          {currentUserId === course.instructorId && (
293	            <Link to={`/instructor/${course.id}`}>
294	              <Button variant="outline" size="sm" className="shrink-0">
295	                <Pencil className="mr-1.5 size-3.5" />
296	                Edit Course
297	              </Button>
298	            </Link>
299	          )}
300	        </div>
301	        <p className="mb-4 text-lg text-muted-foreground">
302	          {course.description}
303	        </p>
304	        <div className="flex items-center gap-4 text-sm text-muted-foreground">
305	          <span className="flex items-center gap-1.5">
306	            <UserAvatar
307	              name={course.instructorName}
308	              avatarUrl={course.instructorAvatarUrl}
309	              className="size-5"
310	            />
311	            {course.instructorName}
312	          </span>
313	          <span className="flex items-center gap-1">
314	            <BookOpen className="size-4" />
315	            {lessonCount} lessons
316	          </span>
317	          {totalDuration > 0 && (
318	            <span className="flex items-center gap-1">
319	              <Clock className="size-4" />
320	              {formatDuration(totalDuration, true, false, false)} total
321	            </span>
322	          )}
323	        </div>
324	      </div>
325	
326	      {/* Two-column: sales copy left, sidebar right */}
327	      <div className="grid gap-8 lg:grid-cols-3">
328	        {/* Left column: sales copy + course content */}
329	        <div className="lg:col-span-2">
330	          {salesCopyHtml ? (
331	            <div
332	              className="prose prose-neutral dark:prose-invert max-w-none"
333	              dangerouslySetInnerHTML={{ __html: salesCopyHtml }}
334	            />
335	          ) : (
336	            <p className="text-muted-foreground">{course.description}</p>
337	          )}
338	
339	          {/* Bottom CTA */}
340	          {!enrolled && !isInstructor && (
341	            <div className="mt-8 rounded-lg border bg-muted/50 p-6">
342	              <h3 className="mb-2 text-lg font-semibold">
343	                Ready to get started?
344	              </h3>
345	              <p className="mb-4 text-sm text-muted-foreground">
346	                Join this course and start learning today.
347	              </p>
348	              {enrollButton}
349	            </div>
350	          )}
351	
352	          <div className="mt-8">
353	            <CourseContent
354	              course={course}
355	              enrolled={enrolled}
356	              isInstructor={isInstructor}
357	              lessonProgressMap={lessonProgressMap}
358	            />
359	          </div>
360	        </div>
361	
362	        {/* Right column: progress/enrollment card */}
363	        <div className="space-y-6">
364	          <Card className="sticky top-6">
365	            <CardHeader>
366	              <h2 className="text-lg font-semibold">
367	                {isInstructor
368	                  ? "Your Course"
369	                  : enrolled
370	                    ? "Your Progress"
371	                    : "Get Started"}
372	              </h2>
373	            </CardHeader>
374	            <CardContent className="space-y-4">
375	              {isInstructor ? (
376	                <Link to={`/instructor/${course.id}`}>
377	                  <Button className="w-full">
378	                    <Pencil className="mr-2 size-4" />
379	                    Manage Course
380	                  </Button>
381	                </Link>
382	              ) : enrolled ? (
383	                <>
384	                  <div className="mb-2 flex items-center justify-between text-sm">
385	                    <span>{progress}% complete</span>
386	                  </div>
387	                  <div className="mb-4 h-2 overflow-hidden rounded-full bg-muted">
388	                    <div
389	                      className="h-full rounded-full bg-primary transition-all"
390	                      style={{ width: `${progress}%` }}
391	                    />
392	                  </div>
393	                  {course.modules.length > 0 &&
394	                    (() => {
395	                      const targetLessonId =
396	                        nextLessonId ?? course.modules[0].lessons[0]?.id;
397	                      return targetLessonId ? (
398	                        <Link
399	                          to={`/courses/${course.slug}/lessons/${targetLessonId}`}
400	                        >
401	                          <Button className="w-full">
402	                            <PlayCircle className="mr-2 size-4" />
403	                            {progress > 0
404	                              ? "Continue Learning"
405	                              : "Start Course"}
406	                          </Button>
407	                        </Link>
408	                      ) : null;
409	                    })()}
410	                  <Link to={teamPurchaseLink}>
411	                    <Button variant="outline" className="w-full">
412	                      <Users className="mr-2 size-4" />
413	                      Buy More Seats
414	                    </Button>
415	                  </Link>
416	                </>
417	              ) : (
418	                enrollButton
419	              )}
420	              <div className="space-y-2 pt-2 text-sm text-muted-foreground">
421	                <div className="flex items-center gap-2">
422	                  <BookOpen className="size-4" />
423	                  <span>{lessonCount} lessons</span>
424	                </div>
425	                <div className="flex items-center gap-2">
426	                  <Clock className="size-4" />
427	                  <span>
428	                    {formatDuration(totalDuration, true, false, false)} total
429	                  </span>
430	                </div>
431	                <div className="flex items-center gap-2">
432	                  <UserAvatar
433	                    name={course.instructorName}
434	                    avatarUrl={course.instructorAvatarUrl}
435	                    className="size-5"
436	                  />
437	                  <span>Taught by {course.instructorName}</span>
438	                </div>
439	                {course.instructorBio && (
440	                  <p className="mt-2 text-xs leading-relaxed">
441	                    {course.instructorBio}
442	                  </p>
443	                )}
444	              </div>
445	            </CardContent>
446	          </Card>
447	        </div>
448	      </div>
449	    </div>
450	  );
451	}
452	
453	function CourseContent({
454	  course,
455	  enrolled,
456	  isInstructor,
457	  lessonProgressMap,
458	}: {
459	  course: {
460	    id: number;
461	    slug: string;
462	    modules: Array<{
463	      id: number;
464	      title: string;
465	      lessons: Array<{
466	        id: number;
467	        title: string;
468	        durationMinutes: number | null;
469	      }>;
470	    }>;
471	  };
472	  enrolled: boolean;
473	  isInstructor: boolean;
474	  lessonProgressMap: Record<number, string>;
475	}) {
476	  return (
477	    <div>
478	      <h2 className="mb-4 text-2xl font-bold">Course Content</h2>
479	      {course.modules.length === 0 ? (
480	        <p className="text-muted-foreground">
481	          No content has been added to this course yet.
482	        </p>
483	      ) : (
484	        <div className="space-y-4">
485	          {course.modules.map((mod) => (
486	            <Card key={mod.id}>
487	              <CardHeader>
488	                <h3 className="font-semibold">
489	                  <Link
490	                    to={`/courses/${course.slug}/${mod.id}`}
491	                    className="hover:underline"
492	                  >
493	                    {mod.title}
494	                  </Link>
495	                </h3>
496	                <p className="text-sm text-muted-foreground">
497	                  {mod.lessons.length} lessons
498	                </p>
499	              </CardHeader>
500	              <CardContent>
501	                <ul className="space-y-2">
502	                  {mod.lessons.map((lesson) => {
503	                    const status = lessonProgressMap[lesson.id];
504	                    const isCompleted =
505	                      status === LessonProgressStatus.Completed;
506	                    const isLessonInProgress =
507	                      status === LessonProgressStatus.InProgress;
508	
509	                    if (isInstructor) {
510	                      return (
511	                        <li key={lesson.id}>
512	                          <Link
513	                            to={`/instructor/${course.id}/lessons/${lesson.id}`}
514	                            className="flex items-center gap-3 rounded-md px-3 py-2 text-sm hover:bg-muted"
515	                          >
516	                            <Pencil className="size-4 shrink-0 text-muted-foreground" />
517	                            <span className="flex-1">{lesson.title}</span>
518	                            {lesson.durationMinutes && (
519	                              <span className="flex items-center gap-1 text-xs text-muted-foreground">
520	                                <Clock className="size-3" />
521	                                {formatDuration(
522	                                  lesson.durationMinutes,
523	                                  true,
524	                                  false,
525	                                  false
526	                                )}
527	                              </span>
528	                            )}
529	                          </Link>
530	                        </li>
531	                      );
532	                    }
533	
534	                    return (
535	                      <li key={lesson.id}>
536	                        {enrolled ? (
537	                          <Link
538	                            to={`/courses/${course.slug}/lessons/${lesson.id}`}
539	                            className="flex items-center gap-3 rounded-md px-3 py-2 text-sm hover:bg-muted"
540	                          >
541	                            {isCompleted ? (
542	                              <CheckCircle2 className="size-4 shrink-0 text-green-500" />
543	                            ) : isLessonInProgress ? (
544	                              <PlayCircle className="size-4 shrink-0 text-blue-500" />
545	                            ) : (
546	                              <Circle className="size-4 shrink-0 text-muted-foreground" />
547	                            )}
548	                            <span className="flex-1">{lesson.title}</span>
549	                            {lesson.durationMinutes && (
550	                              <span className="flex items-center gap-1 text-xs text-muted-foreground">
551	                                <Clock className="size-3" />
552	                                {formatDuration(
553	                                  lesson.durationMinutes,
554	                                  true,
555	                                  false,
556	                                  false
557	                                )}
558	                              </span>
559	                            )}
560	                          </Link>
561	                        ) : (
562	                          <div className="flex items-center gap-3 px-3 py-2 text-sm">
563	                            <Circle className="size-4 shrink-0 text-muted-foreground" />
564	                            <span className="flex-1">{lesson.title}</span>
565	                            {lesson.durationMinutes && (
566	                              <span className="flex items-center gap-1 text-xs text-muted-foreground">
567	                                <Clock className="size-3" />
568	                                {formatDuration(
569	                                  lesson.durationMinutes,
570	                                  true,
571	                                  false,
572	                                  false
573	                                )}
574	                              </span>
575	                            )}
576	                          </div>
577	                        )}
578	                      </li>
579	                    );
580	                  })}
581	                </ul>
582	              </CardContent>
583	            </Card>
584	          ))}
585	        </div>
586	      )}
587	    </div>
588	  );
589	}
590	
591	export function ErrorBoundary({ error }: Route.ErrorBoundaryProps) {
592	  let title = "Something went wrong";
593	  let message = "An unexpected error occurred while loading this course.";
594	
595	  if (isRouteErrorResponse(error)) {
596	    if (error.status === 404) {
597	      title = "Course not found";
598	      message =
599	        "The course you're looking for doesn't exist or may have been removed.";
600	    } else if (error.status === 401) {
601	      title = "Sign in required";
602	      message =
603	        typeof error.data === "string"
604	          ? error.data
605	          : "Please select a user from the DevUI panel.";
606	    } else {
607	      title = `Error ${error.status}`;
608	      message = typeof error.data === "string" ? error.data : error.statusText;
609	    }
610	  }
611	
612	  return (
613	    <div className="flex min-h-[50vh] items-center justify-center p-6">
614	      <div className="text-center">
615	        <AlertTriangle className="mx-auto mb-4 size-12 text-muted-foreground" />
616	        <h1 className="mb-2 text-2xl font-bold">{title}</h1>
617	        <p className="mb-6 text-muted-foreground">{message}</p>
618	        <div className="flex items-center justify-center gap-3">
619	          <Link to="/courses">
620	            <Button variant="outline">Browse Courses</Button>
621	          </Link>
622	          <Link to="/">
623	            <Button>Go Home</Button>
624	          </Link>
625	        </div>
626	      </div>
627	    </div>
628	  );
629	}
