import { Form, Link, useSearchParams, useNavigation, isRouteErrorResponse } from "react-router";
import type { Route } from "./+types/courses";
import { buildCourseQuery, getLessonCountForCourse } from "~/services/courseService";
import { getAllCategories } from "~/services/categoryService";
import { CourseStatus } from "~/db/schema";
import { Card, CardContent, CardFooter, CardHeader } from "~/components/ui/card";
import { Button } from "~/components/ui/button";
import { Skeleton } from "~/components/ui/skeleton";
import { AlertTriangle, BookOpen, Search } from "lucide-react";
import { CourseImage } from "~/components/course-image";
import { UserAvatar } from "~/components/user-avatar";
import { getCurrentUserId } from "~/lib/session";
import { formatPrice } from "~/lib/utils";
import { getUserEnrolledCourses } from "~/services/enrollmentService";
import { calculateProgress, getCompletedLessonCount } from "~/services/progressService";
import { resolveCountry } from "~/lib/country.server";
import { calculatePppPrice } from "~/lib/ppp";

export function meta() {
  return [
    { title: "Browse Courses — Cadence" },
    { name: "description", content: "Browse all available courses" },
  ];
}

export async function loader({ request }: Route.LoaderArgs) {
  const url = new URL(request.url);
  const search = url.searchParams.get("q");
  const category = url.searchParams.get("category");

  const courses = buildCourseQuery(
    search,
    category,
    CourseStatus.Published,
    "newest",
    50,
    0
  );

  const currentUserId = await getCurrentUserId(request);
  const country = await resolveCountry(request);

  // Build a map of courseId -> progress for enrolled courses
  const progressMap = new Map<
    number,
    { progress: number; completedLessons: number }
  >();
  if (currentUserId) {
    const enrollments = getUserEnrolledCourses(currentUserId);
    for (const enrollment of enrollments) {
      progressMap.set(enrollment.courseId, {
        progress: calculateProgress(currentUserId, enrollment.courseId, false, false),
        completedLessons: getCompletedLessonCount(currentUserId, enrollment.courseId),
      });
    }
  }

  const coursesWithLessonCount = courses.map((course) => {
    const userProgress = progressMap.get(course.id);
    const pppPrice = course.pppEnabled
      ? calculatePppPrice(course.price, country)
      : course.price;
    return {
      ...course,
      lessonCount: getLessonCountForCourse(course.id),
      progress: userProgress?.progress ?? null,
      completedLessons: userProgress?.completedLessons ?? null,
      pppPrice,
    };
  });

  const categories = getAllCategories();

  return { courses: coursesWithLessonCount, categories, search, category, currentUserId };
}

function CourseCardSkeleton() {
  return (
    <Card className="h-full">
      <Skeleton className="aspect-video rounded-b-none rounded-t-lg" />
      <CardHeader>
        <Skeleton className="mb-1 h-3 w-16" />
        <Skeleton className="h-5 w-3/4" />
      </CardHeader>
      <CardContent>
        <Skeleton className="mb-1 h-3 w-full" />
        <Skeleton className="h-3 w-2/3" />
      </CardContent>
      <CardFooter className="flex items-center justify-between">
        <Skeleton className="h-3 w-20" />
        <Skeleton className="h-3 w-16" />
      </CardFooter>
    </Card>
  );
}

export function HydrateFallback() {
  return (
    <div className="mx-auto max-w-7xl p-6 lg:p-8">
      <div className="mb-8">
        <Skeleton className="h-9 w-48" />
        <Skeleton className="mt-2 h-5 w-64" />
      </div>
      <div className="mb-8 flex flex-col gap-4 sm:flex-row">
        <Skeleton className="h-10 flex-1" />
        <Skeleton className="h-10 w-40" />
        <Skeleton className="h-10 w-20" />
      </div>
      <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {Array.from({ length: 6 }).map((_, i) => (
          <CourseCardSkeleton key={i} />
        ))}
      </div>
    </div>
  );
}

export default function CourseCatalog({ loaderData }: Route.ComponentProps) {
  const { courses, categories, search, category, currentUserId } = loaderData;
  const [searchParams] = useSearchParams();
  const navigation = useNavigation();
  const isSearching =
    navigation.state === "loading" &&
    navigation.location?.pathname === "/courses";

  return (
    <div className="mx-auto max-w-7xl p-6 lg:p-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold">Browse Courses</h1>
        <p className="mt-1 text-muted-foreground">
          Find courses to expand your skills
        </p>
      </div>

      {/* Search and Filter */}
      <Form method="get" className="mb-8 flex flex-col gap-4 sm:flex-row">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
          <input
            type="text"
            name="q"
            defaultValue={search ?? ""}
            placeholder="Search courses..."
            className="h-10 w-full rounded-md border border-input bg-background pl-10 pr-4 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          />
        </div>
        <select
          name="category"
          defaultValue={category ?? ""}
          className="h-10 rounded-md border border-input bg-background px-3 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <option value="">All Categories</option>
          {categories.map((cat) => (
            <option key={cat.id} value={cat.slug}>
              {cat.name}
            </option>
          ))}
        </select>
        <Button type="submit">Search</Button>
      </Form>

      {/* Course Grid */}
      {isSearching ? (
        <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <CourseCardSkeleton key={i} />
          ))}
        </div>
      ) : courses.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 text-center">
          <BookOpen className="mb-4 size-12 text-muted-foreground/50" />
          <h2 className="text-lg font-medium">No courses found</h2>
          <p className="mt-1 text-sm text-muted-foreground">
            {search || category
              ? "Try adjusting your search or filters."
              : "No published courses are available yet."}
          </p>
        </div>
      ) : (
        <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {courses.map((course) => (
            <Link
              key={course.id}
              to={`/courses/${course.slug}`}
              className="group"
            >
              <Card className="h-full overflow-hidden pt-0 transition-shadow group-hover:shadow-md">
                <div className="aspect-video overflow-hidden">
                  <CourseImage
                    src={course.coverImageUrl}
                    alt={course.title}
                    className="h-full w-full object-cover transition-transform group-hover:scale-105"
                  />
                </div>
                <CardHeader>
                  <div className="mb-1 flex items-center gap-2 text-xs font-medium">
                    <span className="text-primary">{course.categoryName}</span>
                    {currentUserId !== null && course.instructorId === currentUserId && (
                      <span className="inline-flex items-center rounded-full bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary">
                        Your Course
                      </span>
                    )}
                  </div>
                  <h3 className="text-lg font-semibold leading-tight group-hover:text-primary">
                    {course.title}
                  </h3>
                </CardHeader>
                <CardContent>
                  <p className="line-clamp-2 text-sm text-muted-foreground">
                    {course.description}
                  </p>
                </CardContent>
                {course.progress !== null && course.progress > 0 && (
                  <CardContent className="pt-0">
                    <div className="mb-1 flex items-center justify-between text-xs">
                      <span className="text-muted-foreground">
                        {course.completedLessons} / {course.lessonCount} lessons
                      </span>
                      <span className="font-medium">{course.progress}%</span>
                    </div>
                    <div className="h-1.5 overflow-hidden rounded-full bg-muted">
                      <div
                        className="h-full rounded-full bg-primary transition-all"
                        style={{ width: `${course.progress}%` }}
                      />
                    </div>
                  </CardContent>
                )}
                <CardFooter className="flex items-center justify-between text-xs text-muted-foreground">
                  <span className="flex items-center gap-1.5">
                    <UserAvatar
                      name={course.instructorName}
                      avatarUrl={course.instructorAvatarUrl}
                      className="size-5"
                    />
                    {course.instructorName}
                  </span>
                  <span className="font-semibold text-foreground">
                    {course.pppPrice < course.price ? (
                      <span className="flex items-center gap-1.5">
                        <span className="text-xs line-through text-muted-foreground font-normal">
                          {formatPrice(course.price)}
                        </span>
                        {formatPrice(course.pppPrice)}
                      </span>
                    ) : (
                      formatPrice(course.price)
                    )}
                  </span>
                </CardFooter>
              </Card>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
}

export function ErrorBoundary({ error }: Route.ErrorBoundaryProps) {
  let title = "Something went wrong";
  let message = "An unexpected error occurred while loading courses.";

  if (isRouteErrorResponse(error)) {
    title = `Error ${error.status}`;
    message = typeof error.data === "string" ? error.data : error.statusText;
  }

  return (
    <div className="flex min-h-[50vh] items-center justify-center p-6">
      <div className="text-center">
        <AlertTriangle className="mx-auto mb-4 size-12 text-muted-foreground" />
        <h1 className="mb-2 text-2xl font-bold">{title}</h1>
        <p className="mb-6 text-muted-foreground">{message}</p>
        <div className="flex items-center justify-center gap-3">
          <Link to="/">
            <Button>Go Home</Button>
          </Link>
        </div>
      </div>
    </div>
  );
}

import { Link } from "react-router";
import { useState, useEffect } from "react";
import type { Route } from "./+types/home";
import { Button } from "~/components/ui/button";
import { Card, CardContent, CardFooter, CardHeader } from "~/components/ui/card";
import { buildCourseQuery, getLessonCountForCourse } from "~/services/courseService";
import { getAllCategories } from "~/services/categoryService";
import { CourseStatus } from "~/db/schema";
import { BookOpen, GraduationCap, Users, ArrowRight, User, Moon, Sun } from "lucide-react";
import { CourseImage } from "~/components/course-image";
import { DevUI } from "~/components/dev-ui";
import { getAllUsers, getUserById } from "~/services/userService";
import { getCurrentUserId, getDevCountry } from "~/lib/session";
import { getCountryTierInfo, COUNTRIES } from "~/lib/ppp";

export function meta({}: Route.MetaArgs) {
  return [
    { title: "Cadence — Learn at your own pace" },
    { name: "description", content: "A modern course platform for developers. Browse courses, track your progress, and learn at your own pace." },
  ];
}

export async function loader({ request }: Route.LoaderArgs) {
  const courses = buildCourseQuery(null, null, CourseStatus.Published, "newest", 50, 0);
  const featured = courses.slice(0, 3).map((course) => ({
    ...course,
    lessonCount: getLessonCountForCourse(course.id),
  }));
  const categories = getAllCategories();
  const users = getAllUsers();
  const currentUserId = await getCurrentUserId(request);
  const currentUser = currentUserId ? getUserById(currentUserId) : null;
  const devCountry = await getDevCountry(request);
  const countryTierInfo = getCountryTierInfo(devCountry);

  return {
    featuredCourses: featured,
    totalCourses: courses.length,
    totalCategories: categories.length,
    users: users.map((u) => ({ id: u.id, name: u.name, role: u.role })),
    currentUser: currentUser
      ? { id: currentUser.id, name: currentUser.name, role: currentUser.role }
      : null,
    devCountry,
    countryTierInfo,
    countries: COUNTRIES,
  };
}

export default function Home({ loaderData }: Route.ComponentProps) {
  const { featuredCourses, totalCourses, totalCategories, users, currentUser, devCountry, countryTierInfo, countries } = loaderData;
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    setIsDark(document.documentElement.classList.contains("dark"));
  }, []);

  function toggleDarkMode() {
    const next = !isDark;
    setIsDark(next);
    document.documentElement.classList.toggle("dark", next);
    try {
      localStorage.setItem("cadence-theme", next ? "dark" : "light");
    } catch {}
  }

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border">
        <div className="mx-auto flex h-16 max-w-6xl items-center justify-between px-6">
          <Link to="/" className="text-xl font-bold tracking-tight">
            Cadence
          </Link>
          <nav className="flex items-center gap-6">
            <Link
              to="/courses"
              className="text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
            >
              Courses
            </Link>
            <button
              onClick={toggleDarkMode}
              className="rounded-md p-2 text-muted-foreground transition-colors hover:text-foreground"
              title={isDark ? "Switch to light mode" : "Switch to dark mode"}
            >
              {isDark ? <Sun className="size-4" /> : <Moon className="size-4" />}
            </button>
            {currentUser ? (
              <Button asChild size="sm">
                <Link to="/dashboard">Dashboard</Link>
              </Button>
            ) : (
              <>
                <Link
                  to="/login"
                  className="text-sm font-medium text-muted-foreground transition-colors hover:text-foreground"
                >
                  Log In
                </Link>
                <Button asChild size="sm">
                  <Link to="/signup">Sign Up</Link>
                </Button>
              </>
            )}
          </nav>
        </div>
      </header>

      <section className="mx-auto max-w-6xl px-6 py-24 text-center">
        <h1 className="text-5xl font-bold tracking-tight sm:text-6xl">
          Learn to code,
          <br />
          <span className="text-muted-foreground">at your own pace</span>
        </h1>
        <p className="mx-auto mt-6 max-w-2xl text-lg text-muted-foreground">
          Structured courses built by experienced instructors. Track your progress,
          take quizzes, and build real-world skills.
        </p>
        <div className="mt-10 flex items-center justify-center gap-4">
          <Button asChild size="lg">
            <Link to="/courses">
              Browse Courses
              <ArrowRight className="ml-2 size-4" />
            </Link>
          </Button>
        </div>
      </section>

      <section className="border-y border-border bg-muted/50 py-16">
        <div className="mx-auto grid max-w-6xl grid-cols-1 gap-8 px-6 sm:grid-cols-3">
          <div className="text-center">
            <div className="mx-auto mb-3 flex size-12 items-center justify-center rounded-lg bg-primary/10">
              <BookOpen className="size-6 text-primary" />
            </div>
            <p className="text-2xl font-bold">{totalCourses}</p>
            <p className="text-sm text-muted-foreground">Available Courses</p>
          </div>
          <div className="text-center">
            <div className="mx-auto mb-3 flex size-12 items-center justify-center rounded-lg bg-primary/10">
              <GraduationCap className="size-6 text-primary" />
            </div>
            <p className="text-2xl font-bold">{totalCategories}</p>
            <p className="text-sm text-muted-foreground">Categories</p>
          </div>
          <div className="text-center">
            <div className="mx-auto mb-3 flex size-12 items-center justify-center rounded-lg bg-primary/10">
              <Users className="size-6 text-primary" />
            </div>
            <p className="text-2xl font-bold">Self-paced</p>
            <p className="text-sm text-muted-foreground">Learn on your schedule</p>
          </div>
        </div>
      </section>

      {featuredCourses.length > 0 && (
        <section className="mx-auto max-w-6xl px-6 py-20">
          <div className="mb-10 flex items-end justify-between">
            <div>
              <h2 className="text-3xl font-bold tracking-tight">Featured Courses</h2>
              <p className="mt-2 text-muted-foreground">
                Start learning with our most popular courses
              </p>
            </div>
            <Button asChild variant="outline">
              <Link to="/courses">
                View all
                <ArrowRight className="ml-2 size-4" />
              </Link>
            </Button>
          </div>
          <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {featuredCourses.map((course) => (
              <Link key={course.id} to={`/courses/${course.slug}`} className="group">
                <Card className="h-full overflow-hidden pt-0 transition-shadow group-hover:shadow-md">
                  <CourseImage
                    src={course.coverImageUrl}
                    alt={course.title}
                    className="aspect-video w-full object-cover"
                  />
                  <CardHeader>
                    <h3 className="font-semibold leading-snug group-hover:text-primary">
                      {course.title}
                    </h3>
                  </CardHeader>
                  <CardContent>
                    <p className="line-clamp-2 text-sm text-muted-foreground">
                      {course.description}
                    </p>
                  </CardContent>
                  <CardFooter className="flex items-center justify-between text-xs text-muted-foreground">
                    <span className="flex items-center gap-1">
                      <User className="size-3" />
                      {course.instructorName ?? "Instructor"}
